import { buildKnowledgeIndex } from "../src/lib/rag/indexer";
import { resolveRequestedRoots } from "../src/lib/rag/safe-roots";
import { summarizeIndex } from "../src/lib/rag/search";
import { saveKnowledgeIndex } from "../src/lib/rag/store";

async function main() {
  const roots = parseRoots(process.argv.slice(2));
  const safeRoots = resolveRequestedRoots(roots);
  const { index, summary } = await buildKnowledgeIndex({ roots: safeRoots });
  const storePath = await saveKnowledgeIndex(index);

  console.log(
    JSON.stringify(
      {
        ok: true,
        storePath,
        summary,
        index: summarizeIndex(index),
      },
      null,
      2,
    ),
  );
}

function parseRoots(args: string[]) {
  const roots: string[] = [];

  for (let index = 0; index < args.length; index += 1) {
    if (args[index] === "--root" && args[index + 1]) {
      roots.push(args[index + 1]);
      index += 1;
    }
  }

  return roots.length > 0 ? roots : ["."];
}

main().catch((error) => {
  console.error(error instanceof Error ? error.message : error);
  process.exit(1);
});

import { createAgentPlan } from "@/lib/agents/orchestrator";
import { searchKnowledgeIndex } from "@/lib/rag/search";
import { loadKnowledgeIndex } from "@/lib/rag/store";

export const runtime = "nodejs";

type PlanRequest = {
  prompt?: string;
};

export async function POST(request: Request) {
  const body = (await request.json().catch(() => ({}))) as PlanRequest;
  const prompt = body.prompt?.trim();

  if (!prompt) {
    return Response.json(
      { ok: false, error: "Informe um pedido para planejar." },
      { status: 400 },
    );
  }

  const index = await loadKnowledgeIndex();
  const evidence = index
    ? searchKnowledgeIndex(index, prompt, { limit: 6 })
    : [];
  const plan = createAgentPlan(prompt, evidence);

  return Response.json({
    ok: true,
    evidence,
    plan,
  });
}

import { buildKnowledgeIndex } from "@/lib/rag/indexer";
import { resolveRequestedRoots } from "@/lib/rag/safe-roots";
import {
  getKnowledgeIndexMeta,
  saveKnowledgeIndex,
} from "@/lib/rag/store";
import { summarizeIndex } from "@/lib/rag/search";

export const runtime = "nodejs";

type IndexRequest = {
  roots?: string[];
};

export async function GET() {
  const meta = await getKnowledgeIndexMeta();

  return Response.json({
    ok: true,
    indexed: Boolean(meta),
    meta,
  });
}

export async function POST(request: Request) {
  try {
    const body = (await request.json().catch(() => ({}))) as IndexRequest;
    const roots = resolveRequestedRoots(body.roots);
    const { index, summary } = await buildKnowledgeIndex({ roots });
    const storePath = await saveKnowledgeIndex(index);

    return Response.json({
      ok: true,
      storePath,
      summary,
      index: summarizeIndex(index),
    });
  } catch (error) {
    return Response.json(
      {
        ok: false,
        error:
          error instanceof Error
            ? error.message
            : "Falha desconhecida ao indexar workspace.",
      },
      { status: 400 },
    );
  }
}

import { searchKnowledgeIndex, summarizeIndex } from "@/lib/rag/search";
import { loadKnowledgeIndex } from "@/lib/rag/store";
import type { SearchFilters } from "@/lib/rag/types";

export const runtime = "nodejs";

type SearchRequest = {
  query?: string;
  filters?: SearchFilters;
};

export async function POST(request: Request) {
  const body = (await request.json().catch(() => ({}))) as SearchRequest;
  const query = body.query?.trim();

  if (!query) {
    return Response.json(
      { ok: false, error: "Informe uma consulta para buscar na base." },
      { status: 400 },
    );
  }

  const index = await loadKnowledgeIndex();

  if (!index) {
    return Response.json(
      {
        ok: false,
        error: "Nenhum índice encontrado. Rode a indexação primeiro.",
      },
      { status: 404 },
    );
  }

  const results = searchKnowledgeIndex(index, query, body.filters);

  return Response.json({
    ok: true,
    query,
    index: summarizeIndex(index),
    results,
  });
}

