        });
      }
    }
  }

  const generatedAt = new Date().toISOString();
  const summary = {
    files: fileCount,
    chunks: chunks.length,
    ignoredFiles,
    roots,
  };

  return {
    summary,
    index: {
      version: 1,
      rootLabel: roots.map((root) => path.basename(root)).join(", "),
      generatedAt,
      dimensions,
      stats: {
        roots: roots.length,
        files: fileCount,
        chunks: chunks.length,
        dimensions,
        ignoredFiles,
        generatedAt,
      },
      chunks,
    },
  };
}

async function collectFiles(root: string) {
  const files: string[] = [];

  async function walk(current: string) {
    const entries = await fs.readdir(current, { withFileTypes: true });

    for (const entry of entries) {
      const absolute = path.join(current, entry.name);

      if (entry.isDirectory()) {
        if (!isIgnoredDirectory(entry.name)) {
          await walk(absolute);
        }
        continue;
      }

      if (entry.isFile()) {
        files.push(absolute);
      }
    }
  }

  await walk(root);
  return files;
}

function createStableChunkId(
  root: string,
  relativePath: string,
  startLine: number,
  index: number,
) {
  const source = `${root}:${relativePath}:${startLine}:${index}`;
  let hash = 2166136261;

  for (let charIndex = 0; charIndex < source.length; charIndex += 1) {
    hash ^= source.charCodeAt(charIndex);
    hash = Math.imul(hash, 16777619);
  }

  return `chunk_${(hash >>> 0).toString(36)}_${startLine}_${index}`;
}

import path from "node:path";
import { getWorkspaceRoot } from "./config";

export function resolveRequestedRoots(requestedRoots?: string[]) {
  const workspaceRoot = getWorkspaceRoot();
  const allowedRoots = getAllowedRoots(workspaceRoot);
  const roots = requestedRoots && requestedRoots.length > 0 ? requestedRoots : ["."];

  return roots.map((root) => {
    const resolved = path.resolve(workspaceRoot, root);
    const allowed = allowedRoots.some((allowedRoot) => isInside(resolved, allowedRoot));

    if (!allowed) {
      throw new Error(
        `Root fora do escopo permitido: ${resolved}. Configure ZS_ALLOWED_INDEX_ROOTS para permitir outros repositórios.`,
      );
    }

    return resolved;
  });
}

export function getAllowedRoots(workspaceRoot = getWorkspaceRoot()) {
  const configured = process.env.ZS_ALLOWED_INDEX_ROOTS?.split(";")
    .map((entry) => entry.trim())
    .filter(Boolean)
    .map((entry) => path.resolve(workspaceRoot, entry));

  return [workspaceRoot, ...(configured ?? [])];
}

function isInside(candidate: string, parent: string) {
  const relative = path.relative(parent, candidate);
  return relative === "" || (!relative.startsWith("..") && !path.isAbsolute(relative));
}

import { tokenize, summarizeText } from "./text";
import { cosineSimilarity, embedText, tokenOverlapScore } from "./vector";
import type { KnowledgeIndex, SearchFilters, SearchResult } from "./types";

export function searchKnowledgeIndex(
  index: KnowledgeIndex,
  query: string,
  filters: SearchFilters = {},
) {
  const limit = filters.limit ?? 8;
  const queryTokens = tokenize(query);
  const queryVector = embedText(query, index.dimensions);

  return index.chunks
    .filter((chunk) => {
      if (filters.kind && chunk.kind !== filters.kind) {
        return false;
      }

      if (
        filters.pathIncludes &&
        !chunk.path.toLowerCase().includes(filters.pathIncludes.toLowerCase())
      ) {
        return false;
      }

      return true;
    })
    .map<SearchResult>((chunk) => {
      const vectorScore = cosineSimilarity(queryVector, chunk.vector);
      const tokenScore = tokenOverlapScore(queryTokens, chunk.tokens);
      const pathScore = scorePath(queryTokens, chunk.path);
      const signalScore = scoreSignals(queryTokens, chunk.signals);
      const score =
        vectorScore * 0.58 + tokenScore * 0.27 + pathScore * 0.1 + signalScore * 0.05;

      return {
        ...chunk,
        score: Number(score.toFixed(4)),
        highlights: createHighlights(chunk.text, queryTokens),
        reason: createReason(tokenScore, pathScore, signalScore),
      };
    })
    .filter((result) => result.score > 0)
    .sort((a, b) => b.score - a.score)
    .slice(0, limit);
}

export function summarizeIndex(index: KnowledgeIndex) {
  const kinds = new Map<string, number>();
  const signals = new Map<string, number>();

  for (const chunk of index.chunks) {
    kinds.set(chunk.kind, (kinds.get(chunk.kind) ?? 0) + 1);

    for (const signal of chunk.signals) {
      signals.set(signal, (signals.get(signal) ?? 0) + 1);
    }
  }

  return {
    generatedAt: index.generatedAt,
    rootLabel: index.rootLabel,
    stats: index.stats,
    topKinds: sortEntries(kinds).slice(0, 8),
    topSignals: sortEntries(signals).slice(0, 10),
  };
}

